const input = $input.first().json;
const keys = Object.keys(input);
const data = input.data || input.body?.data || {};
const key = data.key || {};
const msg = data.message || {};
return [{json: {keys, remoteJid: key.remoteJid, fromMe: key.fromMe, text: msg.conversation || msg.extendedTextMessage?.text || 'no text', pushName: data.pushName, fullInput: JSON.stringify(input).substring(0,500)}}];
